class Solution:
    def validElements(self, nums):
        n = len(nums)
        res = []
        for i in range(n):
            ok = True
            for j in range(i):
                if nums[j] >= nums[i]:
                    ok = False
                    break
            if not ok:
                ok = True
                for j in range(i + 1, n):
                    if nums[j] >= nums[i]:
                        ok = False
                        break
            if ok:
                res.append(nums[i])
        return res

