class Solution {
public:
    vector<int> validElements(vector<int>& nums) {
        int n = nums.size();
        vector<int> res;
        for (int i = 0; i < n; ++i) {
            bool ok = true;
            for (int j = 0; j < i && ok; ++j)
                if (nums[j] >= nums[i]) ok = false;
            if (!ok) {
                ok = true;
                for (int j = i + 1; j < n && ok; ++j)
                    if (nums[j] >= nums[i]) ok = false;
            }
            if (ok) res.push_back(nums[i]);
        }
        return res;
    }
};

