class Solution {
    public List<Integer> validElements(int[] nums) {
        int n = nums.length;
        int[] sufMax = new int[n];
        sufMax[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--)
            sufMax[i] = Math.max(sufMax[i + 1], nums[i]);
        List<Integer> res = new ArrayList<>();
        long preMax = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            if (preMax == Long.MIN_VALUE || nums[i] > preMax || i == n - 1 || nums[i] > sufMax[i + 1])
                res.add(nums[i]);
            preMax = Math.max(preMax, nums[i]);
        }
        return res;
    }
}

